package com.example.aop;

import org.springframework.aop.framework.ProxyFactory;
import org.springframework.aop.support.AopUtils;

public class ProxyDemo {
    public interface Service {
        void execute();
    }

    public static class ServiceImpl implements Service {
        @Override
        public void execute() {
            System.out.println("Executing business logic...");
        }
    }

    public static void main(String[] args) {
        ServiceImpl target = new ServiceImpl();

        // Forcing JDK Dynamic Proxy (Target implements interface)
        ProxyFactory jdkFactory = new ProxyFactory(target);
        jdkFactory.setProxyTargetClass(false); // Forces JDK proxy
        Service jdkProxy = (Service) jdkFactory.getProxy();

        System.out.println("Is JDK Proxy? " + AopUtils.isJdkDynamicProxy(jdkProxy));
        jdkProxy.execute();

        // Forcing CGLIB Proxy (Subclasses the target directly)
        ProxyFactory cglibFactory = new ProxyFactory(target);
        cglibFactory.setProxyTargetClass(true); // Forces CGLIB proxy
        ServiceImpl cglibProxy = (ServiceImpl) cglibFactory.getProxy();

        System.out.println("Is CGLIB Proxy? " + AopUtils.isCglibProxy(cglibProxy));
        cglibProxy.execute();
    }
}
